/*
 * Phase 2c cycle snapshots on real opcodes for the models the UM20 oracle does not own
 * ( work plan item 4).
 *
 * test_cycle_phase2c.c is the UM20 oracle for the 68020 and owns the 68020 column.  This file
 * fixes the other columns for the same whitelist of instructions (UM20 8.2.6-8.2.18), one real
 * opcode per row, by cycle count, final PC and final A7:
 *
 *  - 68000 / 68010: INVARIANCE.  The values were recorded by running this table (--emit) on the
 *    tree at 6aca23d, the last commit before Phase 2c touched cycle code.  They are not UM00 /
 * DS10 oracle values: they only pin that Phase 2c did not move them.  Rows for 68020-only
 * opcodes (bit-field, CAS, CHK2, PACK, ...) pin the illegal-instruction exception those models
 * take. The 68010 column is post-Phase 2b.  Instructions outside the Phase 2c whitelist (CLR,
 * AND/OR/EOR, MUL.W/DIV.W, ...) have no row here, so this file does not pin their 68000/68010
 * values.
 *  - 68030 / 68EC030: Fourth-column regression snapshots after the Phase 3b--3e
 *    timing connections, across the UM20 8.2.6--8.2.18 whitelist and affected
 *    full-extension rows.  test_cycle_phase3.c owns the independent UM30 row
 *    literals; these values are execution snapshots emitted from this tree, not
 *    a second oracle.  68EC030 shares the 68030 expectation (they share
 *    CYC_PROF_68030) and every row is also run on the 68EC030.
 *  - The last section holds the exception-taken paths that UM20 8.2.16 / 8.2.17 has no row for
 *    (CHK.W, CHK.L, CHK2, divide by zero, invalid MOVEC control register).  They are not part
 * of the UM20 oracle, so the 68020 column is snapshotted here as well.
 *
 * Every row runs on a fresh machine: default registers below, RAM pattern below, one
 * mc68k_execute() of one instruction.  A7 and PC tell which exception, if any, was taken (each
 * vector points at its own handler).  Each section ends with its case count; the count is a
 * literal that must equal both sizeof(array) and the running total, so shrinking or growing a
 * table without updating it fails.
 *
 * `--emit` prints "<section> <row> <model> <cycles> <pc> <a7>" for every row instead of
 * asserting; it is how the expectations below were recorded.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mc68000/cpu.h"
#include "cpu/cpu_internal.h"
#include "memory/memory.h"
#include "memory/bus.h"

#define RAM_SIZE            0x10000u
#define PROGRAM_PC          0x1000u
#define INITIAL_SSP         0x8000u
#define VECTOR_HANDLER_BASE 0x4000u
#define VECTOR_COUNT        256u
#define MAX_ROW_WORDS       6u

/* Operand data.  Every word of these areas is 0x0007, so any byte/word/long read by an EA is a
 * small non-zero value (no divide by zero, in range for the CHK/CHK2 rows). */
#define DATA_BASE              0x1F00u /* starts below A0 so -(A0) reads pattern data too */
#define DATA_SIZE              0x1100u
#define PC_DATA_BASE           0x1010u
#define PC_DATA_SIZE           0x0040u
#define DATA_WORD              0x0007u
/* Long pointer used by the memory-indirect full-extension MOVE row: [A0 + 0x400] -> 0x2500. */
#define INDIRECT_POINTER_ADDR  0x2400u
#define INDIRECT_POINTER_VALUE 0x2500u

/* Stack image for RTE (a7 = FRAME_A7): SR 0x2700, PC 0x1200, format word.  RTR reads the same
 * image (CCR word, then PC); RTS starts two bytes later and pops PC 0x00001200. */
#define FRAME_A7           0x7000u
#define FRAME_SR           0x2700u
#define FRAME_PC           0x1200u
/* Format 1 (throwaway) frames carry M=1 in their SR; RTE then continues with the frame at MSP.
 */
#define THROWAWAY_FORMAT   1u
#define FRAME_SR_THROWAWAY 0x3700u
/* Second frame for the format-1 (throwaway) RTE, popped from MSP: SR 0x2700, PC 0x1300, format
 * 0. */
#define MSP_VALUE          0x7800u
#define MSP_FRAME_PC       0x1300u

#define INDEX_REG_VALUE 0x10u /* D1: the (d8,An,Xn) index */
#define D2_VALUE        0x22u
#define D4_VALUE        0x100u
#define A0_VALUE        0x2000u
#define A1_VALUE        0x3000u
#define A2_VALUE        0x2800u
#define A3_VALUE        0x2900u
#define A6_VALUE        0x7C00u

enum { M68000, M68010, M68020, M68030, MODEL_COUNT };

typedef struct {
    int16_t cycles; /* -1: column not checked */
    uint32_t pc;
    uint32_t a7;
} p2c_snap_t;

#define NC {-1, 0, 0}

typedef struct {
    const char *row;
    uint8_t nwords;
    uint16_t words[MAX_ROW_WORDS];
    uint16_t sr;
    uint32_t d0;
    uint32_t d3;
    uint32_t a7;
    uint8_t rte_format;
    p2c_snap_t snap[MODEL_COUNT];
} p2c_row_t;

typedef struct {
    const char *title;
    const p2c_row_t *rows;
    size_t expected_cases;
    size_t actual_cases;
    int checks_68020;
} p2c_section_t;

