static void w16(uint8_t *p, uint32_t a, uint16_t v) {
    p[a] = v >> 8;
    p[a + 1] = v;
}
static void w32(uint8_t *p, uint32_t a, uint32_t v) {
    w16(p, a, v >> 16);
    w16(p, a + 2, v);
}

/* Fill a RAM image with the vectors, operand data, stack frames and program of one row. */
static void p2c_build_ram(const p2c_row_t *row, uint8_t *ram) {
    w32(ram, 0, INITIAL_SSP);
    w32(ram, 4, PROGRAM_PC);
    for (uint32_t v = 2; v < VECTOR_COUNT; ++v)
        w32(ram, v * 4, VECTOR_HANDLER_BASE + v * 4);
    for (uint32_t a = DATA_BASE; a < DATA_BASE + DATA_SIZE; a += 2)
        w16(ram, a, DATA_WORD);
    for (uint32_t a = PC_DATA_BASE; a < PC_DATA_BASE + PC_DATA_SIZE; a += 2)
        w16(ram, a, DATA_WORD);
    w32(ram, INDIRECT_POINTER_ADDR, INDIRECT_POINTER_VALUE);
    w16(ram, FRAME_A7, row->rte_format == THROWAWAY_FORMAT ? FRAME_SR_THROWAWAY : FRAME_SR);
    w32(ram, FRAME_A7 + 2, FRAME_PC);
    w16(ram, FRAME_A7 + 6, (uint16_t)(row->rte_format << 12));
    w16(ram, MSP_VALUE, FRAME_SR);
    w32(ram, MSP_VALUE + 2, MSP_FRAME_PC);
    for (size_t i = 0; i < row->nwords; ++i)
        w16(ram, PROGRAM_PC + (uint32_t)(i * 2), row->words[i]);
}

static p2c_snap_t p2c_run(const p2c_row_t *row, mc68k_model_t model) {
    uint8_t *ram = calloc(1, RAM_SIZE);
    if (!ram)
        abort();
    p2c_build_ram(row, ram);

    mem_ctx_t *mem = mem_create();
    mem_region_t *region = calloc(1, sizeof(*region));
    if (!mem || !region)
        abort();
    region->data = ram;
    region->size = RAM_SIZE;
    mem_add_region(mem, region);
    mc68k_bus_t bus = bus_make_hooks(mem);
    mc68k_state_t *cpu = mc68k_create_model(&bus, model);
    if (!cpu)
        abort();
    mc68k_reset(cpu);
    cpu->sr = row->sr;
    cpu->d[0] = row->d0;
    cpu->d[1] = INDEX_REG_VALUE;
    cpu->d[2] = D2_VALUE;
    cpu->d[3] = row->d3;
    cpu->d[4] = D4_VALUE;
    cpu->a[0] = A0_VALUE;
    cpu->a[1] = A1_VALUE;
    cpu->a[2] = A2_VALUE;
    cpu->a[3] = A3_VALUE;
    cpu->a[6] = A6_VALUE;
    cpu->a[7] = row->a7;
    cpu->msp = MSP_VALUE;
    p2c_snap_t got;
    got.cycles = (int16_t)mc68k_execute(cpu, 1);
    got.pc = cpu->pc;
    got.a7 = cpu->a[7];
    mc68k_destroy(cpu);
    mem_destroy(mem);
    free(region);
    free(ram);
    return got;
}

static const mc68k_model_t p2c_models[MODEL_COUNT] = {
    MC68K_MODEL_68000,
    MC68K_MODEL_68010,
    MC68K_MODEL_68020,
    MC68K_MODEL_68030,
};
static const char *const p2c_model_names[MODEL_COUNT] = {"68000", "68010", "68020", "68030"};

static void p2c_emit(void) {
    for (size_t s = 0; s < sizeof(p2c_sections) / sizeof(p2c_sections[0]); ++s) {
        for (size_t i = 0; i < p2c_sections[s].actual_cases; ++i) {
            for (int m = 0; m < MODEL_COUNT; ++m) {
                p2c_snap_t g = p2c_run(&p2c_sections[s].rows[i], p2c_models[m]);
                printf("%zu %zu %s %d %X %X\n", s, i, p2c_model_names[m], g.cycles, g.pc, g.a7);
            }
            p2c_snap_t g = p2c_run(&p2c_sections[s].rows[i], MC68K_MODEL_68EC030);
            printf("%zu %zu 68EC030 %d %X %X\n", s, i, g.cycles, g.pc, g.a7);
        }
    }
}

static void p2c_fail(const char *section, const p2c_row_t *row, const char *model,
                     p2c_snap_t want, p2c_snap_t got) {
    fprintf(stderr, "%s: %s on %s: want cycles=%d pc=%X a7=%X, got cycles=%d pc=%X a7=%X\n",
            section, row->row, model, want.cycles, want.pc, want.a7, got.cycles, got.pc,
            got.a7);
    abort();
}

static void p2c_expect(const char *section, const p2c_row_t *row, const char *model,
                       p2c_snap_t want, p2c_snap_t got) {
    if (got.cycles != want.cycles || got.pc != want.pc || got.a7 != want.a7)
        p2c_fail(section, row, model, want, got);
}

/* UM30 §11.6.1 and §11.6.6 I-Cache Case oracle for the MOVE subsection.
 * It intentionally decodes the test opcode instead of using cycles.c or an
 * emulator EA descriptor.  Full forms not printed in §11.6.6 are the same
 * single inference as ops_move.c: normal base is two clocks below its
 * printed base-suppressed counterpart for the matching BD/IIS class. */
static int p2c_move30_source_words(uint16_t ext) {
    unsigned bd = (ext >> 4) & 3;
    unsigned iis = ext & 7;
    if (!(ext & 0x0100))
        return 1;
    return 1 + (bd == 2 ? 1 : bd == 3 ? 2 : 0) + ((iis & 3) == 2 ? 1 : (iis & 3) == 3 ? 2 : 0);
}

static int p2c_move30_fea(int size, int mode, int reg, uint16_t ext) {
    static const uint8_t basic[12][2] = {
        {0, 0}, {0, 0}, {3, 3}, {3, 3}, {4, 4}, {4, 4},
        {6, 6}, {4, 4}, {4, 4}, {4, 4}, {6, 6}, {2, 4},
    };
    static const uint8_t direct[2][3] = {{6, 6, 12}, {6, 8, 12}};
    static const uint8_t indirect[3][3] = {{10, 12, 12}, {12, 14, 14}, {16, 18, 18}};
    int row;
    if (mode != 6 && !(mode == 7 && reg == 3)) {
        row = mode == 7 ? reg + 7 : mode;
        return basic[row][size == 4];
    }
    if (!(ext & 0x0100))
        return 6;
    unsigned bd_raw = (ext >> 4) & 3;
    unsigned iis = ext & 7;
    unsigned bd = bd_raw - 1;
    if (bd_raw == 0 || iis == 4)
        abort();
    if (iis == 0)
        return direct[(ext & 0x0080) != 0][bd];
    return indirect[bd][(iis & 3) - 1];
}

static int p2c_move30_destination(uint16_t ext, int mode, int reg, int register_source) {
    static const uint8_t direct[2][3] = {{6, 8, 12}, {8, 10, 14}};
    static const uint8_t indirect[2][3][3] = {
        {{8, 10, 12}, {10, 12, 14}, {14, 16, 18}},
        {{10, 12, 14}, {12, 14, 16}, {16, 18, 20}},
    };
    int result;
    switch (mode) {
    case 0:
    case 1:
        return 2;
    case 2:
    case 3:
        return register_source ? 3 : 4;
    case 4:
    case 5:
        return 4;
    case 6:
        if (!(ext & 0x0100))
            return 6;
        {
            unsigned bd_raw = (ext >> 4) & 3;
            unsigned iis = ext & 7;
            unsigned bd = bd_raw - 1;
            if (bd_raw == 0 || iis == 4)
                abort();
            result = iis == 0 ? direct[(ext & 0x0080) != 0][bd]
                              : indirect[(ext & 0x0080) != 0][bd][(iis & 3) - 1];
            return result;
        }
    case 7:
        return reg == 0 ? 4 : reg == 1 ? 6 : -1;
    default:
        return -1;
    }
}

static int p2c_move30_cycles(const p2c_row_t *row) {
    uint16_t opcode = row->words[0];
    int size = (opcode & 0x3000) == 0x2000 ? 4 : (opcode & 0x3000) == 0x1000 ? 1 : 2;
    int src_mode = (opcode >> 3) & 7;
    int src_reg = opcode & 7;
    int dst_mode = (opcode >> 6) & 7;
    int dst_reg = (opcode >> 9) & 7;
    int register_source = src_mode <= 1;
    unsigned dst_word = 1;
    if (!register_source && (src_mode == 6 || (src_mode == 7 && src_reg == 3)))
        dst_word = (unsigned)p2c_move30_source_words(row->words[1]);
    int destination =
        p2c_move30_destination(row->words[dst_word], dst_mode, dst_reg, register_source);
    if (destination < 0)
        abort();
    return destination +
           (register_source ? 0 : p2c_move30_fea(size, src_mode, src_reg, row->words[1]));
}

/* UM30 §11.6.14 I-Cache Case for the Phase 2c bit-field EA matrix.  This is
 * deliberately separate from op_bf(): the table's '*' is CIEA, not FEA. */
static uint32_t p2c_bitfield30_reg(const p2c_row_t *row, unsigned reg) {
    switch (reg) {
    case 0:
        return row->d0;
    case 1:
        return INDEX_REG_VALUE;
    case 2:
        return D2_VALUE;
    case 3:
        return row->d3;
    case 4:
        return D4_VALUE;
    default:
        return 0;
    }
}

static int p2c_bitfield30_ciea(uint16_t opcode) {
    int mode = (opcode >> 3) & 7;
    int reg = opcode & 7;
    switch (mode) {
    case 2:
        return 2; /* (An) */
    case 5:
        return 4; /* (d16,An) */
    case 6:
        return 6; /* (d8,An,Xn) */
    case 7:
        return reg == 0 ? 4 : -1; /* (xxx).W */
    default:
        return -1;
    }
}

static int p2c_bitfield30_cycles(const p2c_row_t *row) {
    static const uint8_t dn_cycles[8] = {8, 10, 14, 10, 14, 20, 14, 12};
    static const uint8_t mem4_cycles[8] = {10, 12, 14, 12, 14, 22, 14, 12};
    static const uint8_t mem5_cycles[8] = {14, 18, 22, 18, 22, 28, 22, 18};
    uint16_t opcode = row->words[0];
    uint16_t extension = row->words[1];
    unsigned kind = (opcode >> 8) & 7;
    int mode = (opcode >> 3) & 7;
    if (mode == 0)
        return dn_cycles[kind];
    uint32_t offset = (extension & 0x0800) ? p2c_bitfield30_reg(row, (extension >> 6) & 7)
                                           : (extension >> 6) & 31;
    uint32_t width =
        (extension & 0x20) ? p2c_bitfield30_reg(row, extension & 7) : extension & 31;
    width &= 31;
    if (!width)
        width = 32;
    int start_bit = ((int32_t)offset % 8 + 8) % 8;
    int ciea = p2c_bitfield30_ciea(opcode);
    if (ciea < 0)
        abort();
    return (start_bit + (int)width > 32 ? mem5_cycles[kind] : mem4_cycles[kind]) + ciea;
}

int main(int argc, char **argv) {
    if (argc > 1 && strcmp(argv[1], "--emit") == 0) {
        p2c_emit();
        return 0;
    }
    size_t total = 0;
    for (size_t s = 0; s < sizeof(p2c_sections) / sizeof(p2c_sections[0]); ++s) {
        const p2c_section_t *sec = &p2c_sections[s];
        if (sec->actual_cases != sec->expected_cases) {
            fprintf(stderr, "%s: %zu rows, expected %zu\n", sec->title, sec->actual_cases,
                    sec->expected_cases);
            abort();
        }
        total += sec->actual_cases;
        for (size_t i = 0; i < sec->actual_cases; ++i) {
            const p2c_row_t *row = &sec->rows[i];
            for (int m = 0; m < MODEL_COUNT; ++m) {
                if (row->snap[m].cycles < 0) {
                    if (m == M68020 && !sec->checks_68020)
                        continue; /* the 68020 column is owned by test_cycle_phase2c.c */
                    fprintf(stderr, "%s: %s: %s column is not checked\n", sec->title, row->row,
                            p2c_model_names[m]);
                    abort();
                }
                p2c_snap_t want = row->snap[m];
                if (m == M68030 && sec->rows == p2c_s826)
                    want.cycles = (int16_t)p2c_move30_cycles(row);
                if (m == M68030 && sec->rows == p2c_s8214)
                    want.cycles = (int16_t)p2c_bitfield30_cycles(row);
                p2c_expect(sec->title, row, p2c_model_names[m], want,
                           p2c_run(row, p2c_models[m]));
            }
            /* The 68EC030 shares the 68030 column. */
            p2c_snap_t ec030_want = row->snap[M68030];
            if (sec->rows == p2c_s826)
                ec030_want.cycles = (int16_t)p2c_move30_cycles(row);
            if (sec->rows == p2c_s8214)
                ec030_want.cycles = (int16_t)p2c_bitfield30_cycles(row);
            p2c_expect(sec->title, row, "68EC030", ec030_want,
                       p2c_run(row, MC68K_MODEL_68EC030));
        }
    }
    if (total != P2C_TOTAL_CASES) {
        fprintf(stderr, "total %zu rows, expected %d\n", total, P2C_TOTAL_CASES);
        abort();
    }
    return 0;
}
